import {paintMystic,mysticMesh,MYSTIC_MATERIALS} from './mystic-art.js';
import {creatureBuilder,paintCreatureMesh} from './dungeon-creature-mesh.js';
import {mysticOpen} from './mystic-mechanic.js';
const {cloth:C,gold:G,dark:D}=MYSTIC_MATERIALS,clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x);},lerp=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}),headId=id=>/^(hood-|eye-|crown-)/.test(id);
// The arena rosette is at source y=164; paving's logical center is y=169.5.
// Match its ground anchor without changing the combat grid or damage areas.
export function mysticVisualOffset(b){return{x:0,y:-5.5*((b.arenaSize?.rows??15)-2)/13};}
export function mysticVisualPoint(n,b,beat){let p={x:n.x,y:n.y};if(n===b&&b.mirage.phase===2&&b.mirage.state==='shatter'&&b.mirage.shatterFrom)p=lerp(b.mirage.shatterFrom,b,ease((beat-b.mirage.shatterAt)/3));else{const move=b.mirage.moves.find(w=>w.id===n.id);if(move&&beat>=move.started&&beat<move.due)p=lerp(move.from,move.to,ease(beat-move.started));}const dy=mysticVisualOffset(b).y/16;return{x:p.x-dy/11,y:p.y+dy};}
export function mysticHeadMesh({beat=0,exhausted=false,soft=false,lift=0,nodIntensity=1}={}){const time=beat*60/116,angle=exhausted?(.19+(soft?0:Math.sin(beat*Math.PI)*.035))*nodIntensity:0,m=creatureBuilder({soft:true});for(const f of mysticMesh({time,beat,pose:'idle',soft,includeHidden:true}).filter(f=>headId(f.id))){const points=f.points.map(([x,y,z])=>{const a=z-45,yy=y*Math.cos(angle)-a*Math.sin(angle),zz=y*Math.sin(angle)+a*Math.cos(angle)+45;return[x,yy,zz-20+lift];});m.face(f.id,points,C,p=>p,f.fill);}return m.finish();}
const images=new Map();export const mysticCacheSize=()=>images.size;
function cached(c,key,paint,x,y){let image=images.get(key);if(!image){image=new OffscreenCanvas(348,324);const g=image.getContext('2d');g.scale(3,3);paint(g,58,90);if(images.size>=36){const first=images.keys().next().value;images.get(first).width=1;images.delete(first);}images.set(key,image);}c.drawImage(image,x-58,y-90,116,108);}
function body(c,n,x,y,beat,pose,soft,shadow=true){const time=Math.floor(beat*60/116*24)/24,at=pose==='reveal'?1.9+Math.sin(beat*Math.PI*2)*.08:Math.floor(beat*16)/16,key=['body',time,at.toFixed(3),pose,soft,shadow].join('|');cached(c,key,(g,x,y)=>paintMystic(g,n,x,y,75,time,{beat:at,pose,soft,shadow}),x,y);}
export function paintMysticCombat(c,n,b,beat,project,soft,{showBeam=true}={}){if(!b)return;const m=b.mirage,p=mysticVisualPoint(n,b,beat),v=project(p.x,p.y),real=n===b;
 if(real&&m.phase===2){const exhausted=m.state==='exhausted',u=clamp((beat-m.shatterAt)/3),lower=ease((beat-(m.openAt-1))/.65),returning=m.state==='chase'&&m.chaseStart>m.shatterAt+3,up=ease((beat-m.chaseStart)/.65),nodIntensity=exhausted?lower:returning?1-up:0,lift=m.state==='shatter'?20*(1-ease(u)):exhausted?2-9*lower:returning?-7+9*up:2+(soft?0:Math.sin(beat*1.8)*1.2),sample=Math.floor(beat*24)/24,key=['head',m.state,soft,sample].join('|');c.save();c.globalAlpha*=exhausted?1:.88;cached(c,key,(g,x,y)=>paintCreatureMesh(g,mysticHeadMesh({beat:sample,exhausted:exhausted||returning,soft,lift,nodIntensity}),x,y,94/83,{shadow:true}),v.x/2,v.y/2);c.restore();
  const shot=m.lastShot,age=shot?beat-shot.impact:99;if(showBeam&&age>=0&&age<.5){const to=project(shot.target.x,shot.target.y),fade=1-age/.5;c.save();c.globalAlpha=fade;c.lineWidth=soft?2:4;c.strokeStyle=G[1];c.beginPath();c.moveTo(v.x/2,v.y/2-35);c.lineTo(to.x/2,to.y/2);c.stroke();c.lineWidth=1.5;c.strokeStyle=G[0];c.stroke();c.restore();}return;}
 const clue=real&&['reveal','hunt','open'].includes(m.state);body(c,n,v.x/2,v.y/2,beat,clue?'reveal':m.state==='dance'?'cast':'idle',soft);
 if(clue){const pulse=soft?.5:Math.pow(1-beat%1,3),x=v.x/2+1.5,y=v.y/2-16;c.save();c.strokeStyle=G[0];c.globalAlpha=.55+pulse*.4;c.lineWidth=1.1;c.beginPath();c.moveTo(x,y-4-pulse*2);c.lineTo(x+4+pulse*2,y);c.lineTo(x,y+4+pulse*2);c.lineTo(x-4-pulse*2,y);c.closePath();c.stroke();c.restore();}}
function line(c,points,project,color,width,alpha=1){if(!points.length)return;c.save();c.strokeStyle=color;c.lineWidth=width;c.globalAlpha=alpha;c.lineCap='round';c.lineJoin='round';c.beginPath();points.forEach((p,i)=>{const v=project(p.x,p.y);i?c.lineTo(v.x/2,v.y/2):c.moveTo(v.x/2,v.y/2);});c.stroke();c.restore();}
function flame(c,x,y,height,phase){const sway=Math.sin(phase)*height*.13;c.beginPath();c.moveTo(x-3,y);c.bezierCurveTo(x-6,y-height*.45,x+sway-2,y-height*.6,x+sway,y-height);c.bezierCurveTo(x+2+sway,y-height*.55,x+6,y-height*.35,x+3,y);c.quadraticCurveTo(x,y+2,x-3,y);c.closePath();c.fill();}
export function paintMysticGround(c,b,beat,project,soft,{showFire=true,showBeam=true}={}){const m=b.mirage,fire=m.fire.filter(f=>beat>=f.born&&beat<f.until);c.save();
 for(const f of showFire?fire:[]){const v=project(f.x,f.y),x=v.x/2,y=v.y/2,warm=beat<f.activeAt,fade=clamp((f.until-beat)/.7);c.globalAlpha=fade*(warm?.32:.78);c.fillStyle=warm?G[1]:C[2];c.beginPath();c.ellipse(x,y,11,5,0,0,Math.PI*2);c.fill();for(const [dx,dy]of[[1,0],[0,1],[1,1],[-1,1]])if(fire.some(q=>q.x===f.x+dx&&q.y===f.y+dy)){const q=project(f.x+dx,f.y+dy);c.strokeStyle=warm?G[1]:C[2];c.lineWidth=9;c.beginPath();c.moveTo(x,y);c.lineTo(q.x/2,q.y/2);c.stroke();}if(!warm){c.globalAlpha=fade*.9;c.fillStyle=G[1];flame(c,x,y,soft?8:11+2*Math.sin(beat*7+f.x*2+f.y),beat*6+f.x);c.fillStyle=G[0];flame(c,x,y,soft?5:6+Math.sin(beat*9+f.y),beat*7+f.y);}}
 c.restore();const w=m.shot;if(w&&showBeam){const pulse=soft?.55:.45+.35*Math.pow(1-beat%1,3);line(c,[w.from,w.tiles.at(-1)||w.target],project,G[1],4,pulse);line(c,[w.from,w.tiles.at(-1)||w.target],project,G[0],1,pulse);const v=project(w.target.x,w.target.y);c.save();c.strokeStyle=G[0];c.lineWidth=1.5;c.beginPath();c.moveTo(v.x/2-7,v.y/2-5);c.lineTo(v.x/2+7,v.y/2+5);c.moveTo(v.x/2+7,v.y/2-5);c.lineTo(v.x/2-7,v.y/2+5);c.stroke();c.restore();}
 if(m.state==='shatter'){const age=clamp((beat-m.shatterAt)/3),origin=m.shatterFrom||b,p=project(origin.x,origin.y);p.y+=mysticVisualOffset(b).y*2;c.save();c.globalAlpha=(1-age)*.9;const source=mysticMesh({time:0,beat:0,pose:'idle',soft:true}).filter(f=>!headId(f.id)),parts=creatureBuilder({soft:true});for(const f of source){const side=f.points.reduce((a,p)=>a+p[0],0)<0?-1:1;parts.face(f.id,f.points.map(([x,y,z])=>[x+side*age*(soft?8:26),y+age*10,z+Math.sin(age*Math.PI)*(soft?3:15)-age*22]),C,p=>p,f.fill);}paintCreatureMesh(c,parts.finish(),p.x/2,p.y/2,75/83,{shadow:false});if(!soft){c.fillStyle=G[1];for(let i=0;i<18;i++){const angle=i*2.4,r=age*45;c.fillRect(p.x/2+Math.cos(angle)*r,p.y/2-25+Math.sin(angle)*r*.6-age*10,2,2);}}c.restore();}
 if(m.phase===1)for(const copy of m.copies)if(copy.hp===0&&beat-copy.goneAt>=0&&beat-copy.goneAt<.8){const u=(beat-copy.goneAt)/.8,p=mysticVisualPoint(copy,b,beat),v=project(p.x,p.y);c.save();c.globalAlpha=(1-u)*.7;body(c,copy,v.x/2,v.y/2-u*(soft?0:7),beat,'idle',soft,false);c.restore();}}
